{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈苟安",
      "role": "protagonist",
      "identity": "普通上班族，无限流副本参与者",
      "traits": ["极度怕死", "观察力敏锐", "嘴贫话痨", "逻辑缜密", "表面怂包内心倔强"],
      "overt_motivation": "只想在副本中活下来，回到现实世界继续躺平生活",
      "covert_motivation": "证明自己不是废物，即使没有金手指也能靠智慧生存",
      "secret_fear": "害怕发现自己其实很勇敢，一旦承认这一点就再也无法回到安全的躺平状态",
      "misperception_of_other": "认为林清漪是个冷酷无情的任务机器，实际上她也在寻找真相",
      "hidden_connection": "他的观察天赋与林清漪的身世秘密有关联"
    },
    {
      "name": "林清漪",
      "role": "deuteragonist",
      "identity": "资深副本玩家，神秘组织成员",
      "traits": ["冷静理性", "身手矫健", "情感封闭", "原则性强", "隐藏温柔"],
      "overt_motivation": "完成组织任务，揭露副本背后的真相",
      "covert_motivation": "寻找失踪的妹妹，解开家族诅咒",
      "secret_fear": "害怕自己的情感会成为他人的弱点，导致更多人因她而死",
      "misperception_of_other": "认为陈苟安只是个贪生怕死的累赘，实际上他的观察力能看穿她的伪装",
      "hidden_connection": "她的妹妹曾在陈苟安参与的第一个副本中失踪"
    }
  ],
  "supporting_characters": [
    {
      "name": "老周",
      "function": "助力",
      "identity": "副本老玩家，便利店老板",
      "description": "表面是普通便利店老板，实际上是副本世界的'情报贩子'，欠陈苟安一个人情，经常提供关键信息但收费昂贵"
    },
    {
      "name": "沈墨",
      "function": "阻碍",
      "identity": "反派BOSS，无限流系统管理者",
      "description": "优雅冷酷的系统管理者，认为人类需要通过极端考验才能进化，将陈苟安视为有趣的实验品"
    },
    {
      "name": "小七",
      "function": "反转点",
      "identity": "新人玩家，技术宅",
      "description": "看似无害的技术宅新人，实际上是沈墨安插的眼线，但在关键时刻被陈苟安的真诚打动而背叛沈墨"
    }
  ],
  "relationship_dynamics": "陈苟安和林清漪初期互相嫌弃（他觉得她冷血，她觉得他懦弱），中期因共同危机被迫合作建立信任（他用观察力帮她找到线索，她用实力保护他），后期发现彼此的秘密后经历信任危机（他发现她是组织成员，她发现他隐瞒了关键信息），最终选择坦诚面对共同对抗真正的敌人。老周作为助力提供情报但有自己的算盘，沈墨作为阻碍不断设下陷阱，小七作为反转点在关键时刻改变局势。"
}"}

